// Testien alkuperäisen (täytetyn) ajolistan lähde, jota testit käyttävät aidon
// jaetun tiedoston sijaisena: siinä on 36 muiden ajureiden päiväkirjausta ja 417
// kaavaa, joiden on säilyttävä. Sovelluksen upotettu pohja (lib/templates-data.ts)
// on puhdistettu kirjauksista, joten tämä lähde on erillinen testiresurssi.
export const realPamarkSource=Buffer.from("","base64");
export function rawPamarkBytes():Uint8Array{return new Uint8Array(realPamarkSource);}
